*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #0f1117;
  --color-card: #1a1d27;
  --color-border: #2e3147;
  --color-border-hover: #5b60a0;
  --color-accent: #7c83f5;
  --color-accent-hover: #a0a6ff;
  --color-text: #e2e4f0;
  --color-text-muted: #8b8fa8;
  --color-error: #f87171;
  --color-success: #4ade80;
  --color-radio-bg: #12141e;
  --color-label-hover: #23263a;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --transition: 150ms ease;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  padding: 1.5rem;
}

/* ── Skip link ───────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 100;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ── Card ────────────────────────────────────────── */
.card {
  width: 100%;
  max-width: 520px;
  background: var(--color-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.subtitle {
  margin-top: 0.35rem;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Form field ──────────────────────────────────── */
.form-field {
  margin-top: 2rem;
}

fieldset {
  border: none;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 1rem;
}

/* ── Radio group ─────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-radio-bg);
  cursor: pointer;
  transition:
    border-color var(--transition),
    background-color var(--transition);
  user-select: none;
}

.radio-label:hover {
  border-color: var(--color-border-hover);
  background: var(--color-label-hover);
}

/* Hide native radio visually but keep it accessible */
.radio-label input[type="radio"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom radio circle */
.radio-custom {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 2px solid var(--color-border-hover);
  background: transparent;
  display: flex;
  align-items: center;
  justify-content: center;
  transition:
    border-color var(--transition),
    background-color var(--transition);
}

.radio-custom::after {
  content: "";
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--color-accent);
  opacity: 0;
  transform: scale(0.5);
  transition:
    opacity var(--transition),
    transform var(--transition);
}

/* Checked state */
.radio-label:has(input:checked) {
  border-color: var(--color-accent);
  background: #1e2038;
}

.radio-label:has(input:checked) .radio-custom {
  border-color: var(--color-accent);
  background: rgba(124, 131, 245, 0.15);
}

.radio-label:has(input:checked) .radio-custom::after {
  opacity: 1;
  transform: scale(1);
}

/* Focus-visible ring on the label row */
.radio-label:has(input:focus-visible) {
  outline: 2px solid var(--color-accent);
  outline-offset: 2px;
}

.radio-text {
  font-size: 0.9375rem;
  font-weight: 500;
}

/* ── Error message ───────────────────────────────── */
.error-message {
  margin-top: 0.75rem;
  font-size: 0.875rem;
  color: var(--color-error);
  display: flex;
  align-items: center;
  gap: 0.375rem;
}

.error-message[hidden] {
  display: none;
}

.form-field.has-error .radio-label {
  border-color: var(--color-error);
}

/* ── Submit button ───────────────────────────────── */
.submit-btn {
  margin-top: 2rem;
  width: 100%;
  padding: 0.8125rem 1.5rem;
  background: var(--color-accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition:
    background-color var(--transition),
    transform var(--transition);
}

.submit-btn:hover {
  background: var(--color-accent-hover);
}

.submit-btn:active {
  transform: translateY(1px);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--color-accent-hover);
  outline-offset: 3px;
}

/* ── Success message ─────────────────────────────── */
.success-message {
  margin-top: 1.25rem;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--color-success);
}

.success-message[hidden] {
  display: none;
}

.success-message svg {
  fill: currentColor;
  flex-shrink: 0;
}

/* ── Reflow at 320px ─────────────────────────────── */
@media (max-width: 360px) {
  .card {
    padding: 1.75rem 1.25rem;
  }
}

/* ── Forced colors ───────────────────────────────── */
@media (forced-colors: active) {
  .radio-custom {
    border-color: ButtonText;
  }

  .radio-label:has(input:checked) .radio-custom::after {
    background: Highlight;
  }

  .submit-btn {
    forced-color-adjust: none;
    background: Highlight;
    color: HighlightText;
  }

  .submit-btn:focus-visible {
    outline: 2px solid ButtonText;
  }
}
