:root {
  --color-bg: #0f1117;
  --color-card: #1a1d27;
  --color-border: #2e3147;
  --color-border-hover: #5b60a0;
  --color-accent: #7c83f5;
  --color-accent-hover: #a0a6ff;
  --color-text: #e2e4f0;
  --color-text-muted: #8b8fa8;
  --color-error: #f87171;
  --color-success: #4ade80;
  --color-radio-bg: #12141e;
  --color-label-hover: #23263a;
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --transition: 150ms ease;
}

body {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  padding: 1.5rem;
}

/* ── Skip link ───────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--color-accent);
  color: #fff;
  padding: 0.5rem 1rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  z-index: 100;
  text-decoration: none;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ── Card ────────────────────────────────────────── */
.card {
  width: 100%;
  max-width: 520px;
  background: var(--color-card);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2.5rem 2rem;
  box-shadow: 0 8px 40px rgba(0, 0, 0, 0.5);
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.subtitle {
  margin-top: 0.35rem;
  color: var(--color-text-muted);
  font-size: 0.9375rem;
}

/* ── Form field ──────────────────────────────────── */
.form-field {
  margin-top: 2rem;
}

fieldset {
  border: none;
}

legend {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 1rem;
}

/* ── Radio group ─────────────────────────────────── */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 0.625rem;
}

.radio-label {
  display: flex;
  align-items: center;
  gap: 0.875rem;
  padding: 0.875rem 1rem;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background: var(--color-radio-bg);
  cursor: pointer;
  transition:
    border-color var(--transition),
    background-color var(--transition);
  user-select: none;
}

